#include "UiModel.h"
#include <algorithm>
#include <time.h>
void UiModel::setEvents(const std::vector<UiEvent>& events){recent=events;std::sort(recent.begin(),recent.end(),[](const UiEvent&a,const UiEvent&b){return a.timestamp==b.timestamp?a.id>b.id:a.timestamp>b.timestamp;});if(recent.size()>20)recent.resize(20);}
static String stamp(uint64_t seconds){if(seconds<1700000000)return "time pending";time_t t=seconds;struct tm tm;gmtime_r(&t,&tm);char buf[24];strftime(buf,sizeof(buf),"%m-%d %H:%M:%S",&tm);return String(buf)+" UTC";}
void UiModel::draw(DisplayAdapter& d,const String& ssid,const String& ip,const String& wifiState,const String& listenerState,size_t pending,size_t freeBytes,size_t capacity){
 d.clear(0xffff);d.text(5,5,page==UiPage::History?"HISTORY":"LIVE CAPTURE",0x0000);
 if(page==UiPage::LiveCapture||page==UiPage::History){d.text(5,27,"WiFi "+wifiState+" "+ssid,0x0000);d.text(5,48,"IP "+ip,0x0000);d.text(5,69,"TCP "+listenerState+" Q:"+String(pending),0x0000);d.button(175,5,60,25,"WiFi");d.button(115,5,55,25,page==UiPage::History?"Live":"History");d.text(5,83,"Flash "+String((capacity-freeBytes)/1024)+"/"+String(capacity/1024)+"K"+(freeBytes<70000?" FULL":""),0x0000);for(size_t i=0;i<recent.size()&&i<4;i++){const auto&e=recent[i];int y=97+i*53;d.text(5,y,stamp(e.timestamp),0x0000);d.text(5,y+17,e.ip+" "+String(e.bytes)+"B "+e.format,0x0000);d.text(5,y+34,(e.simulated?"SIMULATED ":"RECEIVED ")+String(e.incomplete?"INCOMPLETE":e.uploaded?"UPLOADED":"PENDING"),0x0000);}if(recent.empty())d.text(5,110,"Waiting for TCP data",0x0000);}
 else if(page==UiPage::RawHex||page==UiPage::RawText){d.button(5,30,70,30,"Back");d.button(85,30,65,30,"HEX");d.button(160,30,75,30,"TEXT");d.text(5,70,selectedId.substring(0,22),0x0000);size_t n=std::min(selectedRaw.size(),(size_t)96);for(size_t row=0;row<(n+7)/8;row++){String line;for(size_t j=row*8;j<n&&j<row*8+8;j++){uint8_t b=selectedRaw[j];if(page==UiPage::RawHex){if(b<16)line+="0";line+=String(b,HEX);line+=" ";}else line+=(b>=32&&b<=126)?(char)b:'.';}d.text(5,96+row*18,line,0x0000);}d.text(5,302,String(selectedRaw.size())+" bytes (first 96)",0x0000);}
 else {d.text(5,32,"WiFi setup",0x0000);d.text(5,55,"SSID: "+wifiSsid,0x0000);d.text(5,76,"Password: "+String(wifiPassword.length(),'*'),0x0000);d.button(5,100,110,30,editingPassword?"Password":"SSID");d.button(125,100,110,30,"Connect");const String keys="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";for(int i=0;i<36;i++){int x=5+(i%6)*39,y=140+(i/6)*25;d.text(x,y,String(keys[i]),0x0000);}d.button(5,293,65,25,"Back");d.button(80,293,70,25,"Delete");d.button(160,293,75,25,"Clear");}
}
void UiModel::onTouch(int x,int y){if(x<0||x>=240||y<0||y>=320)return;if(page==UiPage::LiveCapture||page==UiPage::History){if(y<32&&x>=180){page=UiPage::WiFiSettings;return;}if(y>=97){size_t i=(y-97)/53;if(i<recent.size()&&i<4){selectedId=recent[i].id;selectedRaw.clear();page=UiPage::RawHex;}}}
 else if(page==UiPage::RawHex||page==UiPage::RawText){if(y>=30&&y<65){if(x<80)page=UiPage::History;else if(x<155)page=UiPage::RawHex;else page=UiPage::RawText;}}
 else if(page==UiPage::WiFiSettings){if(y>=100&&y<135){if(x<120)editingPassword=!editingPassword;else connectRequested=true;}else if(y>=140&&y<290){int col=(x-5)/39,row=(y-140)/25;if(x>=5&&col<6&&row<6){const String keys="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";(editingPassword?wifiPassword:wifiSsid)+=keys[row*6+col];}}else if(y>=293){if(x<75)page=UiPage::LiveCapture;else if(x<155){String&v=editingPassword?wifiPassword:wifiSsid;if(v.length())v.remove(v.length()-1);}else (editingPassword?wifiPassword:wifiSsid)="";}}
}
